import{_ as a,o,c as i,a5 as t}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Verification","description":"","frontmatter":{},"headers":[],"relativePath":"feature/trend-s3-daily-replay/test.md","filePath":"feature/trend-s3-daily-replay/test.md"}'),r={name:"feature/trend-s3-daily-replay/test.md"};function l(n,e,s,d,c,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h1><h2 id="neo4j-preflight-resilience" tabindex="-1">Neo4j preflight resilience <a class="header-anchor" href="#neo4j-preflight-resilience" aria-label="Permalink to &quot;Neo4j preflight resilience&quot;">​</a></h2><h3 id="verification-results-2026-10-31" tabindex="-1">Verification results (2026-10-31) <a class="header-anchor" href="#verification-results-2026-10-31" aria-label="Permalink to &quot;Verification results (2026-10-31)&quot;">​</a></h3><ul><li>PASS: 13 isolated Python unit tests in <code>keep-local-only/test_neo4j_preflight.py</code> and 9 regression tests in <code>keep-local-only/test_replay_readiness.py</code> (22 tests passing): <ul><li>First probe succeeds: 1 attempt, no delay, proceed cleanly.</li><li>DNS fails once then succeeds: 2 attempts, 1 delay (2s backoff), returns success.</li><li>DNS fails all 3 attempts: bounded to 3 attempts, raises safe <code>REPLAY_NEO4J_DNS_UNAVAILABLE</code>.</li><li>Connection/routing fails all attempts: bounded retry, raises safe <code>REPLAY_NEO4J_CONNECTION_UNAVAILABLE</code>.</li><li>Timeout: enforces per-attempt and total deadline budget, raises safe <code>REPLAY_NEO4J_TIMEOUT</code>.</li><li>Auth failure: immediate fail on attempt 1 without retry, raises <code>REPLAY_NEO4J_AUTH_FAILED</code>.</li><li>TLS/SSL failure: immediate fail on attempt 1 without retry, raises <code>REPLAY_NEO4J_TLS_FAILED</code>.</li><li>Missing APOC: immediate fail on attempt 1 without retry, raises <code>REPLAY_APOC_UNAVAILABLE</code>.</li><li>Cancellation / lease loss: cooperative cancellation during backoff sleep, immediately raises <code>asyncio.CancelledError</code>.</li><li>Recursive cause / context inspection: correctly extracts root cause when wrapped in driver <code>ServiceUnavailable</code>.</li></ul></li><li>PASS: Web CI in <code>brandhub-web</code> (<code>npx tsc -b --noEmit</code> and <code>npm run lint</code> with 0 errors).</li><li>PASS: Localized error guidance in <code>vi/admin.json</code> and <code>en/admin.json</code> under <code>admin.trendReplay.errors.*</code> for all recognized error codes, with fallback to raw error code and recovery hint. Start/Resume button remains active and accessible on <code>FAILED</code> and <code>INTERRUPTED</code> statuses.</li><li>PASS: Verified Redis active lease is <code>None</code> before touching service configurations.</li></ul><h2 id="s3-replay-source-separation-crawler-key-support" tabindex="-1">S3 replay source separation &amp; crawler key support <a class="header-anchor" href="#s3-replay-source-separation-crawler-key-support" aria-label="Permalink to &quot;S3 replay source separation &amp; crawler key support&quot;">​</a></h2><p>Verify <code>TREND_REPLAY_S3_BUCKET=crawler-social</code> and <code>TREND_REPLAY_S3_PREFIX=</code> separation from <code>S3_BUCKET_NAME=brandhubmedia</code>, empty-prefix root discovery, configured-prefix enforcement when non-empty, <code>dd-MM-yyyy</code> + <code>YYYYMMDD</code>/<code>YYYY-MM-DD</code> matching and conflicting-date exclusion, immutable pinned job bucket/prefix/ETag across config changes, Business optional prefix forwarding, Web bucket badge + optional prefix validation + vi/en copy, browser QA, Web CI, and read-only live preview against <code>crawler-social</code> without starting AI execution.</p><h3 id="s3-replay-source-separation-result-2026-10-31" tabindex="-1">S3 replay source separation result (2026-10-31) <a class="header-anchor" href="#s3-replay-source-separation-result-2026-10-31" aria-label="Permalink to &quot;S3 replay source separation result (2026-10-31)&quot;">​</a></h3><ul><li>PASS: 24 isolated Python tests in <code>keep-local-only/test_daily_replay.py</code> and <code>keep-local-only/test_replay_v3.py</code> (1 external Redis QA test deselected): independent <code>TREND_REPLAY_S3_BUCKET=crawler-social</code> / <code>TREND_REPLAY_S3_PREFIX=</code> vs <code>S3_BUCKET_NAME=brandhubmedia</code>, empty-prefix (<code>&quot;&quot;</code>) root discovery on <code>crawler-social</code>, non-empty prefix boundary enforcement, <code>dd-MM-yyyy</code> + <code>YYYYMMDD_HHMMSS</code> / <code>YYYY-MM-DD</code> date parsing and conflicting-date rejection (<code>ignored_keys</code>), and <code>ReplayJobs.list()</code> returning active <code>bucket</code>/<code>default_prefix</code> while preserving pinned job <code>bucket</code>/<code>prefix</code>/<code>ETag</code> after settings change.</li><li>PASS: Java <code>mvn compile</code> and <code>keep-local-only/TrendReplaySmoke.java</code> verified <code>TrendReplayRequest</code> and <code>AdminTrendReplayService</code> optional/null/blank/trimmed prefix forwarding and 31-day validation.</li><li>PASS: Web CI (<code>npm run lint</code>, <code>npx tsc -b --noEmit</code>, <code>npm run build</code> with 0 errors) and Playwright mocked browser QA (<code>keep-local-only/replay-v3-browser.js</code> + <code>replay-v3-old-preview.js</code>): <code>s3://crawler-social</code> header badge, <code>default_prefix</code> population and blank root-prefix preview submission, 31-day &amp; future-date validation, <code>vi</code>/<code>en</code> locales and light/dark themes at 375/768/1440px with 0 layout overflow or console/page errors.</li><li>PASS: Read-only live <code>crawler-social</code> preview check (<code>POST http://localhost:8082/api/v1/ai/trends/replays/preview</code> with <code>{&quot;start_date&quot;: &quot;2026-10-25&quot;, &quot;end_date&quot;: &quot;2026-10-30&quot;, &quot;prefix&quot;: &quot;&quot;}</code>): returned HTTP 200 (<code>status=PREVIEW</code>, <code>bucket=crawler-social</code>, <code>prefix=&quot;&quot;</code>, <code>ignored_keys=6</code>) with 5 discovered days and 118 total files (<code>2026-10-26</code>: 20, <code>2026-10-27</code>: 23, <code>2026-10-28</code>: 24, <code>2026-10-29</code>: 26, <code>2026-10-30</code>: 25). No replay execution, AI model call, or DB write was invoked.</li></ul><h2 id="multi-platform-update" tabindex="-1">Multi-platform update <a class="header-anchor" href="#multi-platform-update" aria-label="Permalink to &quot;Multi-platform update&quot;">​</a></h2><p>Check mixed-platform adaptation, missing/preserved/future/invalid timestamps, unsupported platform failure, deterministic S3 date/platform hints, 25-row batch checkpoints, V2 start rejection, oldest-day processing and resume. Mock browser: preview validation, file platform labels/counts, stages, old preview read-only, error/empty/progress/results, vi/en light/dark at 375/768/1440. Run Web CI; no real provider or persistence calls.</p><h3 id="multi-platform-result-2026-10-31" tabindex="-1">Multi-platform result (2026-10-31) <a class="header-anchor" href="#multi-platform-result-2026-10-31" aria-label="Permalink to &quot;Multi-platform result (2026-10-31)&quot;">​</a></h3><ul><li>PASS: 33 isolated Python tests (one external Redis QA test deselected), including adapter timestamps/metadata, mixed sources, filename hints, envelope platform preservation, 25/25/1 batching, actual platform counts, V3 creation and V2 start rejection, existing order/resume/preflight regressions.</li><li>PASS: browser mocks for invalid dates, preview, three platform labels, one explicit Start, completion/persistence/counts/results and old V2 preview guidance with no Start. Vietnamese/English, light/dark, 375/768/1440px; fixed existing hidden progress element causing mobile horizontal overflow.</li><li>PASS: Web CI, zero errors; existing 189 lint warnings and large-bundle warning remain. QA sources/logs/screenshots ignored in keep-local-only; no tracked tests added.</li><li>No live S3/provider/DB calls, no operational replay launch, no cleanup/seed/migration. Live crawler, queue consumer and scoring/persistence algorithms unchanged.</li></ul><h2 id="isolated-verification" tabindex="-1">Isolated verification <a class="header-anchor" href="#isolated-verification" aria-label="Permalink to &quot;Isolated verification&quot;">​</a></h2><p>Reject invalid/broad/escaped prefixes, invalid IDs, future/reversed dates, more than 31 days, more than 500 objects, oversized files and malformed JSON. Discovery must paginate, group by an unambiguous key date and pin reads to the previewed ETag.</p><p>Use fake S3/model/graph/vector services and a disposable Redis instance. Verify oldest-day-first processing, all file batches before daily aggregation, previous days only in the history window, duplicate handling and original source dates. Failures block later days; explicit resume skips completed checkpoints. Missing checkpoints and changed source objects must block instead of silently rebuilding.</p><p>Verify preflight checks Neo4j/APOC, Chroma and finite nonzero 384d vectors before file/model work; failures leave extraction checkpoints untouched. Verify replay tracking keys and history roots are isolated and normal live defaults remain intact.</p><p>Check Admin authorization, internal-key protection, date validation and start/resume auditing. On Web, check preview invalidation, duplicate Start prevention, polling, errors/results, vi/en, keyboard interaction and light/dark responsive layouts.</p><p>All executable QA files and generated artifacts stay in ignored keep-local-only folders. This document is a shared verification plan, not executable test code. Never flush shared Redis or call paid models as part of isolated QA.</p><h2 id="verification-result-—-2026-10-26" tabindex="-1">Verification result — 2026-10-26 <a class="header-anchor" href="#verification-result-—-2026-10-26" aria-label="Permalink to &quot;Verification result — 2026-10-26&quot;">​</a></h2><p>93 checks passed: 89 existing regression checks and four local behavior repros. Coverage includes replay, normal-pipeline compatibility, runtime readiness, caption generation, RAG ingestion, Ambassador API/client, Commercial image API, video parameters/styles, scheduling/event-loop behavior and trend persistence. Worker/model and graph/vector calls were mocked; Redis was disposable. These checks do not establish real worker availability or performance under load.</p><p>The four passing repros confirm unresolved behavior, not fixes:</p><ol><li>A stale same-day replay can update graph data while Redis keeps a newer snapshot.</li><li>Global resolution can cluster same-label/name entities across Brand namespaces.</li><li>An archived replay can populate the live cache when no newer snapshot exists.</li><li>An in-flight blocking vector write can finish after async task cancellation.</li></ol><p>See the known limitations in spec.md and remaining work in task.md. Require an explicitly authorized runtime test for real S3 reads, paid AI or shared persistence; inspect daily publication and resolution status rather than treating HTTP 202 as successful completion.</p>',23)])])}const m=a(r,[["render",l]]);export{h as __pageData,m as default};
